content:
A \textbf{function} $f$ from set $A$ to set $B$, written $f: A \rightarrow B$,
is a relation from $A$ to $B$ such that \textbf{every element of $A$ is assigned
to exactly one element of $B$}.

\vspace{0.4cm}
\begin{center}
\begin{tabular}{|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Term} & \textbf{Meaning} \\
\hline
\textbf{Domain} & The set $A$ --- inputs of $f$ \\
\hline
\textbf{Codomain} & The set $B$ --- all possible outputs \\
\hline
\textbf{Range / Image} & $\{f(a) \mid a \in A\} \subseteq B$ --- actual outputs \\
\hline
$f(a)$ & The \textbf{image} of $a$ under $f$; $a$ is the \textbf{preimage} of $f(a)$ \\
\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Key Points:}}
\begin{itemize}[leftmargin=1.5em]
    \item Every element of $A$ must be mapped --- no element can be left out.
    \item Each element of $A$ maps to \textbf{exactly one} element of $B$
          (no splitting).
    \item Different elements of $A$ may map to the \textbf{same} element of $B$.
    \item The range is always a subset of the codomain:
          $\text{range}(f) \subseteq B$.
    \item A function is a special case of a relation: one that is
          \textbf{total} and \textbf{functional}.
\end{itemize}

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Difference between Relation and Function:}}
\begin{itemize}[leftmargin=1.5em]
    \item A \textbf{relation} allows an element of $A$ to map to zero,
          one, or many elements of $B$.
    \item A \textbf{function} requires each element of $A$ to map to
          \textbf{exactly one} element of $B$.
\end{itemize}

\textit{(Past Paper 2025 Q1(vi) directly asks: ``Differentiate between a
Function and a Relation.'')}

\vspace{0.5cm}

Determine which of the following are valid functions from $A = \{1,2,3\}$
to $B = \{a,b,c\}$:

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\begin{center}
\begin{tabular}{|c|l|c|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Mapping} & \textbf{Assigned pairs} & \textbf{Function?} & \textbf{Reason} \\
\hline
$f_1$ & $1\mapsto a,\; 2\mapsto b,\; 3\mapsto c$ &
\textcolor{darkgreen}{\checkmark} & Each input has exactly one output \\
\hline
$f_2$ & $1\mapsto a,\; 2\mapsto a,\; 3\mapsto b$ &
\textcolor{darkgreen}{\checkmark} & Repetition in output is allowed \\
\hline
$f_3$ & $1\mapsto a,\; 2\mapsto b$ &
\textcolor{red}{$\times$} & Element 3 has no image \\
\hline
$f_4$ & $1\mapsto a,\; 1\mapsto b,\; 2\mapsto c,\; 3\mapsto c$ &
\textcolor{red}{$\times$} & Element 1 maps to two outputs \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
\textbf{For $f_1$:} domain $= \{1,2,3\}$, codomain $= \{a,b,c\}$,
range $= \{a,b,c\}$.

\textbf{For $f_2$:} domain $= \{1,2,3\}$, codomain $= \{a,b,c\}$,
range $= \{a,b\} \subsetneq B$ (proper subset of codomain).

\vspace{0.5cm}

A function $f: A \rightarrow B$ is \textbf{one-to-one} (or \textit{injective})
if different elements of $A$ always map to different elements of $B$:
\[
    f \text{ is injective} \iff
    \forall a_1, a_2 \in A,\; f(a_1) = f(a_2) \Rightarrow a_1 = a_2
\]

\textbf{Equivalently (contrapositive):}
\[
    a_1 \neq a_2 \Rightarrow f(a_1) \neq f(a_2)
\]

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Key Points:}}
\begin{itemize}[leftmargin=1.5em]
    \item No two distinct inputs share the same output.
    \item \textbf{To prove injective:} assume $f(a_1) = f(a_2)$ and show $a_1 = a_2$.
    \item \textbf{To disprove:} find $a_1 \neq a_2$ with $f(a_1) = f(a_2)$.
    \item In a function diagram: no two arrows point to the same output.
    \item Requires $|A| \leq |B|$ for a finite injective function to exist.
\end{itemize}

\vspace{0.5cm}

A function $f: A \rightarrow B$ is \textbf{bijective} (or a \textit{one-to-one
correspondence}) if it is \textbf{both injective and surjective}:

\vspace{0.3cm}
\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Injective} & \textbf{Surjective} & \textbf{Bijective?} \\
\hline
\textcolor{darkgreen}{\checkmark} & \textcolor{darkgreen}{\checkmark} &
\textcolor{darkgreen}{\checkmark\ Yes} \\
\hline
\textcolor{darkgreen}{\checkmark} & \textcolor{red}{$\times$} &
\textcolor{red}{$\times$\ No} \\
\hline
\textcolor{red}{$\times$} & \textcolor{darkgreen}{\checkmark} &
\textcolor{red}{$\times$\ No} \\
\hline
\textcolor{red}{$\times$} & \textcolor{red}{$\times$} &
\textcolor{red}{$\times$\ No} \\
\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Key Points:}}
\begin{itemize}[leftmargin=1.5em]
    \item A bijection establishes a \textbf{perfect pairing} between $A$ and $B$.
    \item For finite sets: $f: A \to B$ is bijective iff $|A| = |B|$ and $f$
          is injective (or surjective --- either one implies the other when
          $|A| = |B|$).
    \item A function has an inverse if and only if it is \textbf{bijective}.
    \item Past Papers 2021 Q6, 2022 Q6(b), 2024 Q1(x): all test bijectivity.
\end{itemize}

\vspace{0.5cm}




\begin{center}
\begin{tikzpicture}[
    nd/.style={circle, draw=primaryblue, fill=primaryblue!20,
               minimum size=0.5cm, font=\small},
    arr/.style={->, thick, color=primaryblue},
    lbl/.style={font=\bfseries\small, text=primaryblue}
]


\begin{scope}[shift={(-7,0)}]
    \node[lbl] at (0, 3.2) {One-to-One};
    \node[font=\small, text=darkgray] at (0, 2.8) {(not onto)};
    % domain
    \node[nd] (a1) at (-1, 2.0) {};
    \node[nd] (a2) at (-1, 1.0) {};
    \node[nd] (a3) at (-1, 0.0) {};
