    \draw[arr] (a2) -- (b1);
    \draw[arr] (a3) -- (b2);
    \node[font=\small, text=darkgray] at (-1,-1.5) {$A$};
    \node[font=\small, text=darkgray] at ( 1,-1.5) {$B$};
\end{scope}

\end{tikzpicture}
\end{center}
\begin{center}
\textcolor{darkgray}{\small\textit{Figure 3.1: The four types of functions.
Bijective has a perfect pairing; into leaves some outputs unreached.}}
\end{center}

\vspace{0.5cm}

Determine whether the following functions are bijective from $\mathbb{R}$
to $\mathbb{R}$:
\begin{enumerate}[label=(\alph*), leftmargin=2em]
    \item $f(x) = -3x + 4$
    \item $f(x) = -3x^2 + 7$
    \item $f(x) = \dfrac{x+1}{x+2}$
    \item $f(x) = x^3 + 1$
\end{enumerate}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{(a)} $f(x) = -3x + 4$

\textit{Injective:} Suppose $f(x_1) = f(x_2)$.
\[
    -3x_1 + 4 = -3x_2 + 4 \implies -3x_1 = -3x_2 \implies x_1 = x_2
\]
\textcolor{darkgreen}{\checkmark\ Injective.}

\textit{Surjective:} For any $y \in \mathbb{R}$, solve $-3x + 4 = y$:
$x = \dfrac{4-y}{3} \in \mathbb{R}$. \textcolor{darkgreen}{\checkmark\ Surjective.}

\textcolor{darkgreen}{\textbf{Bijective.}}

\vspace{0.3cm}
\textbf{(b)} $f(x) = -3x^2 + 7$

\textit{Injective?} $f(1) = -3 + 7 = 4$ and $f(-1) = -3 + 7 = 4$.
So $f(1) = f(-1)$ but $1 \neq -1$. \textcolor{red}{$\times$\ Not injective.}

\textit{Surjective?} The range of $-3x^2 + 7$ is $(-\infty, 7]$ since $-3x^2 \leq 0$.
So $y = 8$ has no preimage. \textcolor{red}{$\times$\ Not surjective.}

\textcolor{red}{\textbf{Not bijective.} (Neither injective nor surjective.)}

\vspace{0.3cm}
\textbf{(c)} $f(x) = \dfrac{x+1}{x+2}$

\textit{Domain issue:} $f$ is undefined at $x = -2$, so the domain is not all of
$\mathbb{R}$. Therefore $f: \mathbb{R} \to \mathbb{R}$ as stated is \textbf{not a
valid function}. \textcolor{red}{\textbf{Not bijective.}}

\vspace{0.3cm}
\textbf{(d)} $f(x) = x^3 + 1$

\textit{Injective:} Suppose $f(x_1) = f(x_2)$.
\[
    x_1^3 + 1 = x_2^3 + 1 \implies x_1^3 = x_2^3 \implies x_1 = x_2
\]
(cube root is unique over $\mathbb{R}$). \textcolor{darkgreen}{\checkmark\ Injective.}

\textit{Surjective:} For any $y \in \mathbb{R}$, set $x = \sqrt[3]{y-1} \in \mathbb{R}$.
Then $f(x) = (y-1) + 1 = y$. \textcolor{darkgreen}{\checkmark\ Surjective.}

\textcolor{darkgreen}{\textbf{Bijective.}}

\vspace{0.5cm}

Let $f: \mathbb{R} \rightarrow \mathbb{R}$ with $f(x) = x^2$.
Is $f$ invertible?

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
A function is invertible if and only if it is \textbf{bijective}.
We check both conditions.

\vspace{0.3cm}
\textbf{Injective?}
$f(2) = 4$ and $f(-2) = 4$, but $2 \neq -2$.
\textcolor{red}{$\times$\ Not injective.}

\textbf{Surjective?}
For $y = -1$: we need $x^2 = -1$, which has no real solution.
\textcolor{red}{$\times$\ Not surjective.}

\vspace{0.3cm}
Since $f$ is \textbf{neither injective nor surjective} over $\mathbb{R}$,
it is \textbf{not bijective}.

\textcolor{darkgreen}{\textbf{Conclusion:}}
\[
    \boxed{f(x) = x^2 \text{ is \textbf{NOT} invertible as } f: \mathbb{R} \rightarrow \mathbb{R}}
\]

\textcolor{accentorange}{\textbf{Note:}} If we restrict the domain to $\mathbb{R}^+$
and codomain to $\mathbb{R}^+$, then $f(x) = x^2$ \textit{becomes} bijective
and its inverse is $f^{-1}(y) = \sqrt{y}$.

\vspace{0.5cm}

\textbf{(a)} Let $f: \{a,b,c\} \rightarrow \{1,2,3\}$ with $f(a)=2$, $f(b)=3$, $f(c)=1$.
Is $f$ invertible? If yes, find $f^{-1}$.

\textbf{(b)} Let $f: \{w,x,y,z\} \rightarrow \{0,1,2,3\}$ with $f(w)=3$, $f(x)=1$,
$f(y)=0$, $f(z)=2$. Is $f$ a bijection?

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{(a)} Check injection and surjection:

$f(a)=2,\, f(b)=3,\, f(c)=1$ --- all outputs are distinct.
\textcolor{darkgreen}{\checkmark\ Injective.}

Range $= \{1,2,3\} = $ codomain.
\textcolor{darkgreen}{\checkmark\ Surjective.}

\textcolor{darkgreen}{\textbf{Bijective and therefore invertible.}}

Inverse: swap inputs and outputs.
\[
    f^{-1}(1) = c,\quad f^{-1}(2) = a,\quad f^{-1}(3) = b
\]
\[
    \boxed{f^{-1}: \{1,2,3\} \rightarrow \{a,b,c\}}
\]

\vspace{0.3cm}
\textbf{(b)} $|domain| = 4 = |codomain|$.

All outputs: $\{3,1,0,2\} = \{0,1,2,3\} = $ codomain.
\textcolor{darkgreen}{\checkmark\ Surjective.}

All outputs are distinct.
\textcolor{darkgreen}{\checkmark\ Injective.}

\textcolor{darkgreen}{\textbf{$f$ is a bijection.}} \textcolor{darkgreen}{\checkmark}

\vspace{0.5cm}

Define a function. Describe one-to-one, onto, into and bijective functions.
Give an example of each with a diagram.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Function:} A rule assigning each element of domain $A$ to exactly one
element of codomain $B$.

\vspace{0.3cm}
\begin{center}
\begin{tabular}{|l|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Type} & \textbf{Condition} & \textbf{Example ($\mathbb{Z} \to \mathbb{Z}$)} \\
\hline
One-to-one & $f(a)=f(b) \Rightarrow a=b$ & $f(x) = 2x$ \\
\hline
Onto & range $=$ codomain & $f(x) = x - 1$ \\
\hline
Into & range $\subsetneq$ codomain & $f(x) = x^2$ (range: $\mathbb{Z}^+ \cup \{0\}$) \\
\hline
Bijective & one-to-one AND onto & $f(x) = x + 5$ \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
\textbf{Verification of $f(x) = 2x$ (one-to-one, not onto):}

\textit{Injective:} $2x_1 = 2x_2 \Rightarrow x_1 = x_2$. \textcolor{darkgreen}{\checkmark}

\textit{Not surjective:} $y = 1$ has no preimage since $2x = 1 \Rightarrow x = \frac{1}{2} \notin \mathbb{Z}$.
\textcolor{red}{$\times$}

\vspace{0.3cm}
\textbf{Verification of $f(x) = x+5$ (bijective):}

\textit{Injective:} $x_1+5 = x_2+5 \Rightarrow x_1 = x_2$. \textcolor{darkgreen}{\checkmark}

\textit{Surjective:} For any $y \in \mathbb{Z}$, $x = y-5 \in \mathbb{Z}$ and $f(x) = y$.
\textcolor{darkgreen}{\checkmark}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{\faLightbulb\ Section 3.1 Summary --- Functions: Types \& Properties}}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Four Types at a Glance:}}

\vspace{0.2cm}
\begin{center}
\begin{tabular}{|l|l|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Type} & \textbf{Condition} & \textbf{Range vs Codomain} & \textbf{Requires} \\
\hline
Injective  & No two inputs share output & range $\subseteq B$   & $|A| \leq |B|$ \\
\hline
Surjective & Every output is reached    & range $= B$           & $|A| \geq |B|$ \\
\hline
Bijective  & Both above                 & range $= B$, 1-1      & $|A| = |B|$ \\
\hline
Into       & Some outputs unreached     & range $\subsetneq B$  & $|A| < |B|$ typical \\
\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Proof Strategy:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{To prove injective:} Assume $f(a_1) = f(a_2)$. Derive $a_1 = a_2$.
    \item \textbf{To prove surjective:} Take arbitrary $b \in B$. Construct $a$ with $f(a)=b$.
    \item \textbf{To disprove injective:} Give a concrete $a_1 \neq a_2$ with $f(a_1)=f(a_2)$.
    \item \textbf{To disprove surjective:} Give a concrete $b \in B$ with no preimage.
\end{itemize}

\vspace{0.4cm}
\textcolor{accentorange}{\textbf{Past Paper Connection:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{2020 Q5(b):} $f(x)=x^2$ invertible? $\rightarrow$ Example 3
    \item \textbf{2021 Q6:} Bijective from $\mathbb{R}$ to $\mathbb{R}$ $\rightarrow$ Example 2
    \item \textbf{2022 Q4(b) \& Q6(b):} Finite function invertibility $\rightarrow$ Example 4
    \item \textbf{2024 Q1(x),(xi):} Define bijection; inverse of one-to-one $\rightarrow$ Definitions 3.2--3.5
    \item \textbf{2025 Q1(vi) \& Q3:} Relation vs function; all four types $\rightarrow$ Definitions 3.1--3.5, Example 5
\end{itemize}

\vspace{0.5cm}

Let $f: A \rightarrow B$ and $g: B \rightarrow C$. The \textbf{composition}
of $g$ with $f$, written $g \circ f$ (read: ``$g$ composed with $f$''),
is the function $g \circ f: A \rightarrow C$ defined by:
\[
    (g \circ f)(x) = g(f(x)) \quad \text{for all } x \in A
\]

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Key Points:}}
\begin{itemize}[leftmargin=1.5em]
    \item \textbf{Order matters:} $g \circ f$ means apply $f$ \textit{first},
          then $g$. Read right to left.
    \item $g \circ f \neq f \circ g$ in general (composition is \textbf{not commutative}).
    \item Composition \textbf{is associative:} $(h \circ g) \circ f = h \circ (g \circ f)$.
    \item The \textbf{range of $f$} must be a subset of the \textbf{domain of $g$}
          for $g \circ f$ to be defined.
    \item Composition of two injective functions is injective.
    \item Composition of two surjective functions is surjective.
    \item Composition of two bijections is a bijection.
\end{itemize}

\vspace{0.5cm}

Let $f, g, h: \mathbb{R} \rightarrow \mathbb{R}$ with
$f(x) = 2x + 3$, \; $g(x) = x^2 - 1$, \; $h(x) = \sqrt{x+4}$.

Find: (a) $(g \circ f)(x)$ \quad
      (b) $(f \circ g)(x)$ \quad
      (c) $(g \circ f)(2)$ \quad
      (d) $(h \circ g)(x)$ \quad
      (e) $(f \circ f)(x)$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{(a)} $(g \circ f)(x) = g(f(x)) = g(2x+3) = (2x+3)^2 - 1$
\[
    = 4x^2 + 12x + 9 - 1 = \boxed{4x^2 + 12x + 8}
\]

\textbf{(b)} $(f \circ g)(x) = f(g(x)) = f(x^2 - 1) = 2(x^2 - 1) + 3$
\[
    = 2x^2 - 2 + 3 = \boxed{2x^2 + 1}
\]

\textbf{Note:} $(g \circ f)(x) \neq (f \circ g)(x)$
--- composition is \textcolor{red}{\textbf{not commutative}}.

\vspace{0.3cm}
\textbf{(c)} $(g \circ f)(2) = 4(4) + 12(2) + 8 = 16 + 24 + 8 = \boxed{48}$

\textbf{Verification:} $f(2) = 7$, then $g(7) = 49 - 1 = 48$. \textcolor{darkgreen}{\checkmark}

\vspace{0.3cm}
\textbf{(d)} $(h \circ g)(x) = h(g(x)) = h(x^2-1) = \sqrt{(x^2-1)+4} = \boxed{\sqrt{x^2+3}}$

\vspace{0.3cm}
\textbf{(e)} $(f \circ f)(x) = f(f(x)) = f(2x+3) = 2(2x+3) + 3 = 4x + 6 + 3 = \boxed{4x + 9}$

\vspace{0.5cm}

Let $A = \{1,2,3,4\}$, $f: A \rightarrow A$ and $g: A \rightarrow A$ defined by:
\[
    f = \{(1,3),(2,1),(3,2),(4,4)\} \qquad
    g = \{(1,2),(2,4),(3,1),(4,3)\}
\]
Find: (a) $g \circ f$ \quad (b) $f \circ g$ \quad (c) $f \circ f$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{(a)} $g \circ f$: apply $f$ first, then $g$.

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$x$ & $f(x)$ & $g(f(x))$ & $(g \circ f)(x)$ \\
\hline
1 & 3 & $g(3) = 1$ & 1 \\
\hline
2 & 1 & $g(1) = 2$ & 2 \\
\hline
3 & 2 & $g(2) = 4$ & 4 \\
\hline
4 & 4 & $g(4) = 3$ & 3 \\
\hline
\end{tabular}
\end{center}
\[
    g \circ f = \{(1,1),(2,2),(3,4),(4,3)\}
\]

\textbf{(b)} $f \circ g$: apply $g$ first, then $f$.

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$x$ & $g(x)$ & $f(g(x))$ & $(f \circ g)(x)$ \\
\hline
1 & 2 & $f(2) = 1$ & 1 \\
\hline
2 & 4 & $f(4) = 4$ & 4 \\
\hline
3 & 1 & $f(1) = 3$ & 3 \\
\hline
4 & 3 & $f(3) = 2$ & 2 \\
\hline
\end{tabular}
\end{center}
\[
    f \circ g = \{(1,1),(2,4),(3,3),(4,2)\}
\]

\textbf{(c)} $f \circ f$: apply $f$ twice.

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$x$ & $f(x)$ & $f(f(x))$ & $(f \circ f)(x)$ \\
\hline
1 & 3 & $f(3) = 2$ & 2 \\
\hline
2 & 1 & $f(1) = 3$ & 3 \\
\hline
3 & 2 & $f(2) = 1$ & 1 \\
\hline
4 & 4 & $f(4) = 4$ & 4 \\
\hline
\end{tabular}
\end{center}
\[
    f \circ f = \{(1,2),(2,3),(3,1),(4,4)\}
\]

\textbf{Observation:} $g \circ f \neq f \circ g$.
Composition is \textcolor{red}{\textbf{not commutative}}.

\vspace{0.5cm}

The \textbf{identity function} on a set $A$, written $I_A$ or $\text{id}_A$,
is the function that maps every element to itself:
\[
    I_A: A \rightarrow A, \qquad I_A(x) = x \quad \text{for all } x \in A
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Key Properties:}}
\begin{itemize}[leftmargin=1.5em]
    \item $f \circ I_A = f$ and $I_B \circ f = f$ for any $f: A \rightarrow B$.
    \item The identity function is always bijective.
    \item It plays the same role in function composition that $1$ plays in multiplication.
\end{itemize}

\vspace{0.5cm}

If $f: A \rightarrow B$ is bijective, then $f^{-1}: B \rightarrow A$ exists
and is also bijective.

\vspace{0.5cm}

Find the inverse of $f: \mathbb{R} \rightarrow \mathbb{R}$ where $f(x) = 3x - 7$.

Verify that $f \circ f^{-1} = I$ and $f^{-1} \circ f = I$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Step 1: Verify $f$ is bijective.}

\textit{Injective:} $3x_1 - 7 = 3x_2 - 7 \Rightarrow x_1 = x_2$. \textcolor{darkgreen}{\checkmark}

\textit{Surjective:} For any $y \in \mathbb{R}$, set $x = \dfrac{y+7}{3}$.
Then $f(x) = y$. \textcolor{darkgreen}{\checkmark}

\vspace{0.3cm}
\textbf{Step 2: Find $f^{-1}$.}

Set $y = f(x) = 3x - 7$. Solve for $x$:
\[
    y = 3x - 7 \implies y + 7 = 3x \implies x = \frac{y+7}{3}
\]
\[
    \boxed{f^{-1}(x) = \frac{x+7}{3}}
\]

\textbf{Step 3: Verify.}

$(f \circ f^{-1})(x) = f\!\left(\dfrac{x+7}{3}\right) = 3 \cdot \dfrac{x+7}{3} - 7 = x+7-7 = x = I(x)$
\textcolor{darkgreen}{\checkmark}

$(f^{-1} \circ f)(x) = f^{-1}(3x-7) = \dfrac{(3x-7)+7}{3} = \dfrac{3x}{3} = x = I(x)$
\textcolor{darkgreen}{\checkmark}

\vspace{0.5cm}

Let $f: \{1,2,3,4,5\} \rightarrow \{1,2,3,4,5\}$ be given by:
\[
    f = \{(1,3),\,(2,5),\,(3,4),\,(4,1),\,(5,2)\}
\]

\begin{enumerate}[label=(\alph*), leftmargin=2em]
    \item Show that $f$ is a bijection.
    \item Find $f^{-1}$.
    \item Compute $f^{-1} \circ f^{-1}$.
\end{enumerate}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{(a)} All outputs $\{3,5,4,1,2\} = \{1,2,3,4,5\}$ are distinct and
cover the codomain. \textcolor{darkgreen}{Bijection.} \textcolor{darkgreen}{\checkmark}

\vspace{0.3cm}
\textbf{(b)} Swap inputs and outputs:
\[
    f^{-1} = \{(3,1),\,(5,2),\,(4,3),\,(1,4),\,(2,5)\}
\]

\vspace{0.3cm}
\textbf{(c)} $f^{-1} \circ f^{-1}$: apply $f^{-1}$ twice.

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$x$ & $f^{-1}(x)$ & $f^{-1}(f^{-1}(x))$ & $(f^{-1} \circ f^{-1})(x)$ \\
\hline
1 & 4 & $f^{-1}(4) = 3$ & 3 \\
\hline
2 & 5 & $f^{-1}(5) = 2$ & 2 \\
\hline
3 & 1 & $f^{-1}(1) = 4$ & 4 \\
\hline
4 & 3 & $f^{-1}(3) = 1$ & 1 \\
\hline
5 & 2 & $f^{-1}(2) = 5$ & 5 \\
\hline
\end{tabular}
\end{center}
\[
    f^{-1} \circ f^{-1} = \{(1,3),(2,2),(3,4),(4,1),(5,5)\}
\]

\vspace{0.5cm}

Let $f: \mathbb{R} \rightarrow \mathbb{R}$ with $f(x) = 2x - 1$ and
$g: \mathbb{R} \rightarrow \mathbb{R}$ with $g(x) = x + 4$.

\begin{enumerate}[label=(\alph*), leftmargin=2em]
    \item Find $g \circ f$ and $f \circ g$.
    \item Are $g \circ f$ and $f \circ g$ bijective?
    \item Find $(g \circ f)^{-1}$ and verify using $f^{-1} \circ g^{-1}$.
\end{enumerate}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{(a)}
\[
    (g \circ f)(x) = g(2x-1) = (2x-1)+4 = \boxed{2x + 3}
\]
\[
    (f \circ g)(x) = f(x+4) = 2(x+4)-1 = \boxed{2x + 7}
\]

\vspace{0.3cm}
\textbf{(b)} Both $f$ and $g$ are linear with non-zero slope, hence bijective.
Composition of bijections is bijective.
\textcolor{darkgreen}{\checkmark\ Both $g \circ f$ and $f \circ g$ are bijective.}

\vspace{0.3cm}
\textbf{(c)} Find $(g \circ f)^{-1}$ directly:

Set $y = 2x + 3$, solve for $x$:
\[
    x = \frac{y-3}{2} \implies \boxed{(g \circ f)^{-1}(x) = \frac{x-3}{2}}
\]

\textbf{Verify via $f^{-1} \circ g^{-1}$:}

$f(x) = 2x-1 \Rightarrow f^{-1}(x) = \dfrac{x+1}{2}$

$g(x) = x+4 \Rightarrow g^{-1}(x) = x - 4$

$(f^{-1} \circ g^{-1})(x) = f^{-1}(g^{-1}(x)) = f^{-1}(x-4) = \dfrac{(x-4)+1}{2}
= \dfrac{x-3}{2}$ \textcolor{darkgreen}{\checkmark}

The formula $(g \circ f)^{-1} = f^{-1} \circ g^{-1}$ is confirmed.

