\textcolor{primaryblue}{\textbf{\faLightbulb\ Section 3.2 Summary --- Composition \& Inverse Functions}}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Composition Rules:}}
\begin{itemize}[leftmargin=1.5em]
    \item $(g \circ f)(x) = g(f(x))$ --- apply $f$ first, then $g$.
    \item \textbf{Not commutative:} $g \circ f \neq f \circ g$ in general.
    \item \textbf{Associative:} $(h \circ g) \circ f = h \circ (g \circ f)$.
    \item Composition of injections is injective; surjections is surjective;
          bijections is bijective.
\end{itemize}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Inverse Function Rules:}}
\begin{itemize}[leftmargin=1.5em]
    \item $f^{-1}$ exists $\iff$ $f$ is bijective.
    \item To find $f^{-1}$: set $y = f(x)$, solve for $x$, write $f^{-1}(y) = x$.
    \item $(f^{-1})^{-1} = f$.
    \item $(g \circ f)^{-1} = f^{-1} \circ g^{-1}$ (reverse order!).
    \item $f^{-1} \circ f = I_A$ and $f \circ f^{-1} = I_B$.
\end{itemize}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Step-by-Step: Finding an Inverse}}
\begin{enumerate}[leftmargin=2em]
    \item Verify $f$ is bijective.
    \item Write $y = f(x)$.
    \item Solve algebraically for $x$ in terms of $y$.
    \item Write $f^{-1}(y) = x$ (or replace $y$ with $x$ for standard notation).
    \item Verify: $f(f^{-1}(x)) = x$ and $f^{-1}(f(x)) = x$.
\end{enumerate}

