\textcolor{primaryblue}{\textbf{\faLightbulb\ Section 3.3 Summary --- Recursive Functions \& Recurrence Relations}}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Common Recurrences and Their Solutions:}}

\vspace{0.2cm}
\begin{center}
\begin{tabular}{|l|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Recurrence} & \textbf{Type} & \textbf{Closed Form} \\
\hline
$a_n = a_{n-1} + d$, $a_1 = a$ & Arithmetic & $a_n = a + (n-1)d$ \\
\hline
$a_n = r \cdot a_{n-1}$, $a_0 = a$ & Geometric & $a_n = a \cdot r^n$ \\
\hline
$a_n = 2a_{n-1}+1$, $a_0=3$ & Linear & $a_n = 2^{n+2}-1$ \\
\hline
$H(n) = 2H(n-1)+1$, $H(1)=1$ & Hanoi & $H(n) = 2^n - 1$ \\
\hline
$F(n) = F(n-1)+F(n-2)$ & Fibonacci & No simple closed form \\
\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Iteration Method Steps:}}
\begin{enumerate}[leftmargin=2em]
    \item Write $a_n$ in terms of $a_{n-1}$, substitute again for $a_{n-1}$
          in terms of $a_{n-2}$, and so on.
    \item After $k$ steps, identify the pattern:
          $a_n = 2^k a_{n-k} + \text{(sum terms)}$.
    \item Set $k = n$ (or $k = n-1$) to reach the base case.
    \item Simplify the geometric series:
          $\displaystyle\sum_{i=0}^{k-1} r^i = \frac{r^k - 1}{r - 1}$ for $r \neq 1$.
    \item Verify both the initial condition and one step of the recurrence.
\end{enumerate}

\vspace{0.5cm}

Show that $f(n) = 3n^2 + 5n + 7$ is $O(n^2)$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Step 1: Find witnesses $C$ and $k$.}

For $n \geq 1$: $n \leq n^2$ and $1 \leq n^2$, so:
\[
    3n^2 + 5n + 7 \leq 3n^2 + 5n^2 + 7n^2 = 15n^2
\]

\textbf{Step 2: State the witnesses.}

Choose $C = 15$ and $k = 1$. Then for all $n > 1$:
\[
    |3n^2 + 5n + 7| \leq 15n^2 = C \cdot n^2
\]

\textbf{Step 3: Conclude.}
\[
    \boxed{f(n) = 3n^2 + 5n + 7 = O(n^2)}
\]

\textcolor{accentorange}{\textbf{Note:}} We could also choose $C = 4$, $k = 7$
(tighter), but any valid pair works. The simplest is preferred.

\vspace{0.5cm}

Determine the time complexity of each algorithm segment.
Express your answer in Big-O notation.

\vspace{0.3cm}
\textbf{(a) Linear search:}
\begin{verbatim}
for i = 1 to n:
    if A[i] == target:
        return i
return -1
\end{verbatim}

\textbf{(b) Nested loops:}
\begin{verbatim}
for i = 1 to n:
    for j = 1 to n:
        sum = sum + A[i][j]
\end{verbatim}

\textbf{(c) Binary search:}
\begin{verbatim}
while low <= high:
    mid = (low + high) / 2
    if A[mid] == target: return mid
    elif A[mid] < target: low = mid + 1
    else: high = mid - 1
\end{verbatim}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{(a) Linear search:}

The loop runs at most $n$ times, with $O(1)$ work per iteration.

\textcolor{darkgreen}{\textbf{Complexity: $O(n)$}}

\vspace{0.3cm}
\textbf{(b) Nested loops:}

Outer loop runs $n$ times. For each iteration of the outer loop, the inner loop
also runs $n$ times. Total operations $= n \times n = n^2$.

\textcolor{darkgreen}{\textbf{Complexity: $O(n^2)$}}

\vspace{0.3cm}
\textbf{(c) Binary search:}

Each iteration halves the search space. Starting with $n$ elements:
after $k$ iterations, $\lfloor n/2^k \rfloor$ elements remain.
The loop ends when $n/2^k \leq 1$, i.e.\ $k \geq \log_2 n$.

\textcolor{darkgreen}{\textbf{Complexity: $O(\log n)$}}

\vspace{0.3cm}
\begin{center}
\begin{tabular}{|l|c|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Algorithm} & \textbf{Complexity} & \textbf{Reason} \\
\hline
Linear search  & $O(n)$      & One loop over $n$ elements \\
\hline
Nested loops   & $O(n^2)$    & Two nested loops \\
\hline
Binary search  & $O(\log n)$ & Halving at each step \\
\hline
\end{tabular}
\end{center}

