\newpage

For any integer $a$ and positive integer $d$, there exist \textbf{unique}
integers $q$ (quotient) and $r$ (remainder) with $0 \leq r < d$ such that:
\[
    a = d \cdot q + r
\]
We write $q = a \mathbf{\;div\;} d$ and $r = a \mathbf{\;mod\;} d$.

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Examples:}}
\begin{center}
\begin{tabular}{|c|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$a$ & $d$ & $q = a \div d$ & $r = a \bmod d$ & Check: $dq+r$ \\
\hline
$17$  & $5$ & $3$ & $2$ & $5(3)+2=17$ \textcolor{darkgreen}{\checkmark} \\
\hline
$-11$ & $3$ & $-4$ & $1$ & $3(-4)+1=-11$ \textcolor{darkgreen}{\checkmark} \\
\hline
$0$   & $7$ & $0$ & $0$ & $7(0)+0=0$ \textcolor{darkgreen}{\checkmark} \\
\hline
$100$ & $13$ & $7$ & $9$ & $13(7)+9=100$ \textcolor{darkgreen}{\checkmark} \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
\textcolor{accentorange}{\textbf{Key Rule for Negatives:}} The remainder $r$ must
always satisfy $0 \leq r < d$. So for $a = -11$, $d = 3$:
$q = -4$ (not $-3$) because $-3 \cdot (-4) + 1 = 12 - 11 = 1 \geq 0$. \textit{(Past Paper 2020 Q1(iii): $(-17)\bmod 2 = 1$.)}

\vspace{0.5cm}

Compute each of the following:
\begin{enumerate}[label=(\alph*), leftmargin=2em]
    \item $(-17) \bmod 2$
    \item $(2^{100}) \bmod 3$
    \item $(7^{50}) \bmod 4$
    \item $(11 \cdot 13) \bmod 7$
\end{enumerate}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{(a)} $(-17) \bmod 2$:

$-17 = 2 \cdot (-9) + 1$. Since $r = 1 \geq 0$: \quad $\boxed{(-17)\bmod 2 = 1}$

\vspace{0.3cm}
\textbf{(b)} $(2^{100}) \bmod 3$:

$2 \equiv -1 \pmod{3}$, so $2^{100} \equiv (-1)^{100} = 1 \pmod{3}$.

$\boxed{2^{100} \bmod 3 = 1}$

\vspace{0.3cm}
\textbf{(c)} $(7^{50}) \bmod 4$:

$7 \equiv 3 \equiv -1 \pmod{4}$, so $7^{50} \equiv (-1)^{50} = 1 \pmod{4}$.

$\boxed{7^{50} \bmod 4 = 1}$

\vspace{0.3cm}
\textbf{(d)} $(11 \cdot 13) \bmod 7$:

$11 \bmod 7 = 4$, \quad $13 \bmod 7 = 6$.

$(4 \cdot 6) \bmod 7 = 24 \bmod 7 = 3$.

$\boxed{(11 \cdot 13) \bmod 7 = 3}$

\textbf{Verification:} $11 \times 13 = 143$; $143 = 7 \times 20 + 3$. \textcolor{darkgreen}{\checkmark}

\vspace{0.5cm}

The \textbf{greatest common divisor} of two non-zero integers $a$ and $b$,
written $\gcd(a,b)$, is the largest positive integer that divides both $a$ and $b$:
\[
    \gcd(a,b) = \max\{d \in \mathbb{Z}^+ \mid d \mid a \text{ and } d \mid b\}
\]

\vspace{0.3cm}
\textbf{Least Common Multiple:}
\[
    \text{lcm}(a,b) = \frac{|a \cdot b|}{\gcd(a,b)}
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Key Facts:}}
\begin{itemize}[leftmargin=1.5em]
    \item $\gcd(a,b) = \gcd(b, a \bmod b)$ \quad (used in the Euclidean Algorithm)
    \item $\gcd(a,0) = a$ \quad (base case of Euclidean Algorithm)
    \item If $\gcd(a,b) = 1$, then $a$ and $b$ are \textbf{relatively prime} (coprime).
    \item $\gcd(a,b) \cdot \text{lcm}(a,b) = |a \cdot b|$
\end{itemize}

\vspace{0.5cm}

The \textbf{Euclidean Algorithm} finds $\gcd(a,b)$ by repeated application
of the division algorithm:

\vspace{0.3cm}
\begin{center}
\begin{tabular}{ll}
\textbf{Step 1:} & Divide $a$ by $b$: $a = bq_1 + r_1$, \quad $0 \leq r_1 < b$ \\
\textbf{Step 2:} & Divide $b$ by $r_1$: $b = r_1 q_2 + r_2$ \\
\textbf{Step 3:} & Divide $r_1$ by $r_2$: $r_1 = r_2 q_3 + r_3$ \\
$\vdots$ & Continue until remainder $= 0$ \\
\textbf{Last:}   & $\gcd(a,b) = $ last \textbf{non-zero} remainder \\
\end{tabular}
\end{center}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Why it works:}}
$\gcd(a,b) = \gcd(b, a \bmod b)$. This reduces the problem size at each step
until we reach $\gcd(d, 0) = d$.

\vspace{0.5cm}

Find $\gcd(252, 198)$ and $\text{lcm}(252, 198)$ using the Euclidean Algorithm.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Euclidean Algorithm:}

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Step} & \textbf{Division} & \textbf{Equation} & \textbf{Remainder} \\
\hline
1 & $252 \div 198$ & $252 = 198(1) + 54$ & $r_1 = 54$ \\
\hline
2 & $198 \div 54$  & $198 = 54(3) + 36$  & $r_2 = 36$ \\
\hline
3 & $54 \div 36$   & $54 = 36(1) + 18$   & $r_3 = 18$ \\
\hline
4 & $36 \div 18$   & $36 = 18(2) + 0$    & $r_4 = 0$ \textbf{(stop)} \\
\hline
\end{tabular}
\end{center}

Last non-zero remainder: $\boxed{\gcd(252,198) = 18}$

\textbf{LCM:}
\[
    \text{lcm}(252,198) = \frac{252 \times 198}{18} = \frac{49896}{18} = \boxed{2772}
\]

\textbf{Verification:} $252 = 18 \times 14$ \textcolor{darkgreen}{\checkmark}; $198 = 18 \times 11$ \textcolor{darkgreen}{\checkmark}

\vspace{0.5cm}

Find $\gcd(360, 504)$ and $\text{lcm}(360, 504)$ using prime factorisation.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Prime factorisations:}
\[
    360 = 2^3 \times 3^2 \times 5
    \qquad
    504 = 2^3 \times 3^2 \times 7
\]

\textbf{GCD:} Take the \textbf{minimum} exponent of each common prime:
\[
    \gcd(360,504) = 2^{\min(3,3)} \times 3^{\min(2,2)} = 2^3 \times 3^2 = 8 \times 9 = \boxed{72}
\]

\textbf{LCM:} Take the \textbf{maximum} exponent of each prime:
\[
    \text{lcm}(360,504) = 2^{\max(3,3)} \times 3^{\max(2,2)} \times 5^1 \times 7^1
    = 8 \times 9 \times 5 \times 7 = \boxed{2520}
\]

\textbf{Verify:} $\gcd \times \text{lcm} = 72 \times 2520 = 181440 = 360 \times 504$ \textcolor{darkgreen}{\checkmark}

\vspace{0.5cm}

An integer $p > 1$ is \textbf{prime} if its only positive divisors are $1$ and $p$.
An integer $n > 1$ that is not prime is called \textbf{composite}.

\vspace{0.3cm}
\textbf{Fundamental Theorem of Arithmetic:} Every integer $n > 1$ can be written
as a product of primes in exactly one way (up to order):
\[
    n = p_1^{a_1} \cdot p_2^{a_2} \cdots p_k^{a_k}
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{\faInfoCircle\ Primality Testing:}}
To test if $n$ is prime, check divisibility by all primes up to $\lfloor\sqrt{n}\rfloor$.
If none divides $n$, then $n$ is prime.

\vspace{0.5cm}

Use the extended Euclidean Algorithm to find integers $s$ and $t$ such that:
\[
    \gcd(35, 15) = 35s + 15t
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Step 1: Apply Euclidean Algorithm.}
\begin{align*}
    35 &= 15(2) + 5 \\
    15 &= 5(3)  + 0
\end{align*}
$\gcd(35,15) = 5$.

\vspace{0.3cm}
\textbf{Step 2: Back-substitute.}

From the first equation:
\[
    5 = 35 - 15(2) = 35(1) + 15(-2)
\]

So $s = 1$, $t = -2$.

\textbf{Verification:}
$35(1) + 15(-2) = 35 - 30 = 5 = \gcd(35,15)$ \textcolor{darkgreen}{\checkmark}

\[
    \boxed{\gcd(35,15) = 5 = 35(1) + 15(-2)}
\]

\vspace{0.5cm}

Find the modular inverse of $7$ modulo $26$,
i.e.\ find $x$ such that $7x \equiv 1 \pmod{26}$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Step 1: Apply Euclidean Algorithm to find $\gcd(7,26)$.}
\begin{align*}
    26 &= 7(3) + 5 \\
    7  &= 5(1) + 2 \\
    5  &= 2(2) + 1 \\
    2  &= 1(2) + 0
\end{align*}
$\gcd(7,26) = 1$ (coprime, so the inverse exists). \textcolor{darkgreen}{\checkmark}

\vspace{0.3cm}
\textbf{Step 2: Back-substitute.}
\begin{align*}
    1 &= 5 - 2(2) \\
      &= 5 - 2(7 - 5) = 3(5) - 2(7) \\
      &= 3(26 - 7 \cdot 3) - 2(7) = 3(26) - 9(7) - 2(7) \\
      &= 3(26) - 11(7)
\end{align*}
So $-11(7) \equiv 1 \pmod{26}$.

Since $-11 \equiv 15 \pmod{26}$:
\[
    \boxed{7^{-1} \equiv 15 \pmod{26}}
\]

\textbf{Verify:} $7 \times 15 = 105 = 4(26) + 1 \equiv 1 \pmod{26}$ \textcolor{darkgreen}{\checkmark}

\textit{(This modular inverse is used in the Affine Cipher in Section~3.6.)}

