\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ RSA Step-by-Step:}}
\begin{enumerate}[leftmargin=2em]
    \item Choose primes $p$, $q$. Compute $n = pq$.
    \item Compute $\phi(n) = (p-1)(q-1)$.
    \item Choose $e$ with $\gcd(e, \phi(n)) = 1$.
    \item Find $d = e^{-1} \bmod \phi(n)$ via extended Euclidean.
    \item Encrypt: $C = M^e \bmod n$.
    \item Decrypt: $M = C^d \bmod n$.
\end{enumerate}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Affine Cipher Checklist:}}
\begin{itemize}[leftmargin=1.5em]
    \item Always verify $\gcd(a, 26) = 1$ before proceeding.
    \item Find $a^{-1} \bmod 26$ using the extended Euclidean algorithm.
    \item For decryption: $D(c) = a^{-1}(c - b) \bmod 26$.
          Add 26 if the result is negative.
\end{itemize}

